/** Exhaustive development snapshot. Secrets and binary payloads are excluded, but diagnostic state is intentionally verbose. */
public final class DebugExporter {
    public static final int SCHEMA_VERSION=3;
    private DebugExporter(){}

    public static void exportAndShare(Activity a,VaultDb db){
        android.widget.Toast.makeText(a,"Building exhaustive Cortex debug package…",android.widget.Toast.LENGTH_SHORT).show();
        try{CortexAuditStore.Run r=CortexAuditStore.latest(db);if(r!=null)CortexAuditStore.log(db,r.id,"info","debug_export","export_started","Exhaustive debug export requested by user",null);}catch(Exception ignored){}
        new Thread(()->{try{File f=build(a,db);a.runOnUiThread(()->share(a,f));}catch(Exception e){a.runOnUiThread(()->android.widget.Toast.makeText(a,"Debug export failed: "+e.getMessage(),android.widget.Toast.LENGTH_LONG).show());}},"CortexFullDebugExport").start();
    }

    public static File build(Context c,VaultDb db)throws Exception{
        FeatureStore.ensure(db);TemporalResolver.ensure(db);CoreBrainEngine.ensure(db);ScreenshotLearning.ensure(db);VisualInsightStore.ensure(db);CortexAuditStore.ensure(db);
        SQLiteDatabase s=db.getReadableDatabase();JSONObject root=new JSONObject();root.put("schema_version",SCHEMA_VERSION);root.put("generated_at",iso(System.currentTimeMillis()));root.put("purpose","Cortex exhaustive development diagnostic snapshot");root.put("privacy_note","API keys, encrypted secret values and binary attachment contents are intentionally excluded. Paths, metadata, raw text/OCR/transcripts, model outputs, audit evidence, table rows, schemas and file metadata are included so failures and NOT-RUN features are visible rather than hidden.");
        root.put("app",app(c));root.put("device",device());root.put("environment",environment(c));root.put("runtime_inventory",runtimeInventory(c));root.put("database_health",databaseHealth(s));root.put("database_schema",databaseSchema(s));root.put("feature_status",featureStatus(c,s));root.put("feature_test_catalog",CortexAuditStore.catalogJson());root.put("audit",CortexAuditStore.exportJson(c,db));root.put("memory_stats",memoryStats(s));root.put("screenshot_pipeline",screenshotStats(db,s));root.put("visual_intelligence",visualStats(c,s));root.put("graph_health",graphHealth(s));root.put("smart_inbox_stats",smartInboxStats(db,s));root.put("temporal_stats",temporalStats(s));root.put("self_checks",selfChecks(c,db,s));root.put("filesystem_inventory",filesystemInventory(c));
        JSONObject data=new JSONObject();Cursor tables=s.rawQuery("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name",null);long tableRows=0;while(tables.moveToNext()){String t=tables.getString(0);JSONArray rows=dumpTable(s,t);tableRows+=rows.length();data.put(t,rows);}tables.close();root.put("data",data);JSONObject manifest=new JSONObject();manifest.put("all_application_tables_exported",true);manifest.put("table_count",data.length());manifest.put("total_exported_table_rows",tableRows);manifest.put("blob_policy","BLOB contents are replaced with <BLOB N bytes>; every non-BLOB cell is exported.");manifest.put("secrets_exported",false);manifest.put("binary_attachments_exported",false);root.put("export_manifest",manifest);
        File dir=new File(c.getFilesDir(),"debug_exports");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Could not create debug export directory");String stamp=new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.US).format(new Date());File out=new File(dir,"CortexDebug_v"+versionCode(c)+"_"+stamp+".json");try(Writer w=new BufferedWriter(new OutputStreamWriter(new FileOutputStream(out),java.nio.charset.StandardCharsets.UTF_8),65536)){w.write(root.toString(2));}return out;
    }

    private static JSONObject app(Context c)throws Exception{JSONObject o=new JSONObject();PackageInfo p=c.getPackageManager().getPackageInfo(c.getPackageName(),0);o.put("package",c.getPackageName());o.put("version_name",p.versionName);o.put("version_code",versionCode(c));o.put("db_file_bytes",c.getDatabasePath("cortex.db").exists()?c.getDatabasePath("cortex.db").length():0);o.put("files_dir",c.getFilesDir().getAbsolutePath());o.put("cache_dir",c.getCacheDir().getAbsolutePath());o.put("debug_schema_version",SCHEMA_VERSION);return o;}
    private static long versionCode(Context c){try{PackageInfo p=c.getPackageManager().getPackageInfo(c.getPackageName(),0);return Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode;}catch(Exception e){return 0;}}
    private static JSONObject device()throws Exception{JSONObject o=new JSONObject();o.put("manufacturer",Build.MANUFACTURER);o.put("model",Build.MODEL);o.put("device",Build.DEVICE);o.put("product",Build.PRODUCT);o.put("android_release",Build.VERSION.RELEASE);o.put("sdk",Build.VERSION.SDK_INT);o.put("security_patch",Build.VERSION.SECURITY_PATCH);o.put("abis",new JSONArray(Arrays.asList(Build.SUPPORTED_ABIS)));o.put("timezone",TimeZone.getDefault().getID());o.put("available_processors",Runtime.getRuntime().availableProcessors());o.put("max_heap_bytes",Runtime.getRuntime().maxMemory());o.put("heap_total_bytes",Runtime.getRuntime().totalMemory());o.put("heap_free_bytes",Runtime.getRuntime().freeMemory());return o;}

    private static JSONObject environment(Context c)throws Exception{JSONObject o=new JSONObject();LocalModelManager.Status m=LocalModelManager.status(c);JSONObject model=new JSONObject();model.put("name",LocalModelManager.MODEL_NAME);model.put("file",LocalModelManager.MODEL_FILE);model.put("download_url",LocalModelManager.MODEL_URL);model.put("status",m.label);model.put("transfer_state",m.state);model.put("progress_percent",m.percent);model.put("downloaded_bytes",m.done);model.put("total_bytes",m.total);model.put("partial_bytes",m.partialBytes);model.put("speed_bytes_per_sec",m.speedBytesPerSec);model.put("http_status",m.httpStatus);model.put("retry_count",m.retryCount);model.put("range_supported",m.rangeSupported);model.put("last_progress_at",m.lastProgressAt);model.put("current_url",m.currentUrl);model.put("file_bytes",LocalModelManager.size(c));model.put("file_present",LocalModelManager.filePresent(c));model.put("sha_verified",m.verified);model.put("expected_sha256",LocalModelManager.SHA256);o.put("local_model",model);
        LocalLlmRuntime.State rt=LocalLlmRuntime.state(c);JSONObject runtime=new JSONObject();runtime.put("runtime_version",LocalLlmRuntime.runtimeVersion());runtime.put("state",rt.state);runtime.put("installed",LocalModelManager.runtimeInstalled(c));runtime.put("inference_ready",LocalModelManager.installed(c));runtime.put("self_test_text",rt.selfTestText);runtime.put("error",rt.error);runtime.put("tokens_generated",rt.tokensGenerated);runtime.put("tokens_per_second",rt.tokensPerSecond);runtime.put("duration_ms",rt.durationMs);runtime.put("tested_at",rt.testedAt);runtime.put("system_info",rt.systemInfo);o.put("local_runtime",runtime);
        JSONObject shot=new JSONObject();shot.put("folder_connected",ScreenshotIngestor.tree(c)!=null);shot.put("folder_label",ScreenshotIngestor.treeLabel(c));shot.put("folder_uri",ScreenshotIngestor.tree(c)==null?"":ScreenshotIngestor.tree(c).toString());o.put("screenshot_source",shot);JSONObject cloud=new JSONObject();cloud.put("gemini_configured",GeminiKeyStore.has(c));cloud.put("groq_configured",GroqKeyStore.has(c));cloud.put("secrets_exported",false);o.put("cloud",cloud);JSONObject ocr=new JSONObject();ocr.put("role","supporting evidence only; not source of truth for Visual Intelligence");ocr.put("mlkit_latin","configured");ocr.put("tesseract_arabic",ArabicOcr.modelReady(c)?"offline_ready":"not_ready");ocr.put("worker","WorkManager durable queue");o.put("ocr",ocr);JSONObject vis=new JSONObject();vis.put("worker_state",VisualInsightStore.workerState(c));vis.put("worker_stage",VisualInsightStore.workerStage(c));vis.put("worker_detail",VisualInsightStore.workerDetail(c));vis.put("background_start",VisualInsightStore.existingBackgroundStart(c));o.put("visual_worker",vis);return o;}

    private static JSONObject runtimeInventory(Context c)throws Exception{JSONObject o=new JSONObject();PackageManager pm=c.getPackageManager();int flags=PackageManager.GET_ACTIVITIES|PackageManager.GET_SERVICES|PackageManager.GET_PROVIDERS|PackageManager.GET_RECEIVERS|PackageManager.GET_PERMISSIONS;PackageInfo p=pm.getPackageInfo(c.getPackageName(),flags);o.put("activities",components(p.activities));o.put("services",components(p.services));o.put("providers",components(p.providers));o.put("receivers",components(p.receivers));JSONArray perms=new JSONArray();if(p.requestedPermissions!=null)for(String x:p.requestedPermissions){JSONObject q=new JSONObject();q.put("permission",x);q.put("granted",pm.checkPermission(x,c.getPackageName())==PackageManager.PERMISSION_GRANTED);perms.put(q);}o.put("permissions",perms);o.put("file_provider_resolves",pm.resolveContentProvider(c.getPackageName()+".feedback.files",0)!=null);o.put("notification_listener_enabled",CortexAuditSoakWorker.notificationListenerEnabled(c));o.put("network_connected",CortexAuditSoakWorker.network(c));JSONObject b=new JSONObject();CortexAuditSoakWorker.battery(c,b);o.put("battery",b);return o;}
    private static JSONArray components(ComponentInfo[] xs)throws Exception{JSONArray a=new JSONArray();if(xs!=null)for(ComponentInfo x:xs){JSONObject o=new JSONObject();o.put("name",x.name);o.put("package",x.packageName);o.put("enabled",x.enabled);o.put("exported",x.exported);a.put(o);}return a;}

    private static JSONObject featureStatus(Context c,SQLiteDatabase s)throws Exception{JSONObject o=new JSONObject();o.put("universal_capture","active");o.put("automatic_understanding","active_partial");o.put("ask_cortex",LocalModelManager.installed(c)?"active_local_qwen_routed":"deterministic_fallback_only");o.put("needs_attention","active");o.put("reminders_dates",tableExists(s,"action_temporal")?"active_partial":"inactive");o.put("timeline","active_partial");o.put("notification_memory","service_present_user_permission_dependent");o.put("people_memory",tableExists(s,"memory_facets")?"data_layer_present":"inactive");o.put("projects_context_packs",tableExists(s,"context_packs")?"data_layer_present":"inactive");o.put("prompt_library","active_partial");o.put("screenshot_intelligence",tableExists(s,"visual_insights")?"visual_intelligence_v47_active":"inactive");o.put("screenshot_learning",tableExists(s,"screenshot_intents")?"active":"inactive");o.put("memory_connections",tableExists(s,"relations")?"data_layer_present":"inactive");o.put("smart_inbox","active");o.put("semantic_search",tableExists(s,"embeddings")?"active_partial":"inactive");o.put("daily_weekly_brief","active_partial_or_not_observed");o.put("corrections_learning",tableExists(s,"correction_rules")?"data_layer_present":"inactive");o.put("privacy_controls","partial_with_visual_local_guard");o.put("backup_restore_export","implementation_present_debug_export_active");o.put("integrations","permission_and_provider_dependent");o.put("proactive_cortex","partial");o.put("local_llm_runtime",LocalModelManager.installed(c)?"active_self_test_passed":("testing".equals(LocalLlmRuntime.state(c).state)?"testing":"runtime_bundled_self_test_pending_or_failed"));o.put("full_app_audit",tableExists(s,"cortex_audit_runs")?"active_available":"inactive");return o;}

    private static JSONObject databaseHealth(SQLiteDatabase s)throws Exception{JSONObject o=new JSONObject();JSONArray tables=new JSONArray();Cursor c=s.rawQuery("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name",null);long rows=0;while(c.moveToNext()){String t=c.getString(0);JSONObject x=new JSONObject();long n=count(s,"SELECT COUNT(*) FROM "+qi(t));rows+=n;x.put("table",t);x.put("rows",n);tables.put(x);}c.close();o.put("tables",tables);o.put("total_tables",tables.length());o.put("total_rows",rows);o.put("quick_check",scalar(s,"PRAGMA quick_check(1)"));o.put("foreign_key_issue_rows",rowCount(s,"PRAGMA foreign_key_check"));return o;}
    private static JSONArray databaseSchema(SQLiteDatabase s)throws Exception{JSONArray out=new JSONArray();Cursor c=s.rawQuery("SELECT name,sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name",null);while(c.moveToNext()){String t=c.getString(0);JSONObject o=new JSONObject();o.put("table",t);o.put("create_sql",c.isNull(1)?"":c.getString(1));JSONArray cols=new JSONArray();Cursor q=s.rawQuery("PRAGMA table_info("+qi(t)+")",null);while(q.moveToNext()){JSONObject x=new JSONObject();x.put("cid",q.getInt(0));x.put("name",q.getString(1));x.put("type",q.getString(2));x.put("not_null",q.getInt(3));x.put("default",q.isNull(4)?JSONObject.NULL:q.getString(4));x.put("primary_key",q.getInt(5));cols.put(x);}q.close();o.put("columns",cols);JSONArray idx=new JSONArray();Cursor z=s.rawQuery("PRAGMA index_list("+qi(t)+")",null);while(z.moveToNext()){JSONObject x=new JSONObject();x.put("name",z.getString(1));x.put("unique",z.getInt(2));x.put("origin",z.getString(3));idx.put(x);}z.close();o.put("indexes",idx);out.put(o);}c.close();return out;}

    private static JSONObject memoryStats(SQLiteDatabase s)throws Exception{JSONObject o=new JSONObject();o.put("total",count(s,"SELECT COUNT(*) FROM knowledge_items"));o.put("by_type",group(s,"SELECT type,COUNT(*) FROM knowledge_items GROUP BY type ORDER BY COUNT(*) DESC"));o.put("by_status",group(s,"SELECT status,COUNT(*) FROM knowledge_items GROUP BY status ORDER BY COUNT(*) DESC"));o.put("by_source",group(s,"SELECT source,COUNT(*) FROM knowledge_items GROUP BY source ORDER BY COUNT(*) DESC"));o.put("with_attachment",count(s,"SELECT COUNT(*) FROM knowledge_items WHERE attachment_path IS NOT NULL AND TRIM(attachment_path)<>''"));o.put("with_extracted_text",count(s,"SELECT COUNT(*) FROM knowledge_items WHERE extracted_text IS NOT NULL AND TRIM(extracted_text)<>''"));return o;}
    private static JSONObject screenshotStats(VaultDb db,SQLiteDatabase s)throws Exception{JSONObject o=new JSONObject();String w="type IN ('SCREENSHOT','IMAGE')";o.put("total",count(s,"SELECT COUNT(*) FROM knowledge_items WHERE "+w));o.put("by_status",group(s,"SELECT status,COUNT(*) FROM knowledge_items WHERE "+w+" GROUP BY status ORDER BY COUNT(*) DESC"));o.put("supporting_text_present",count(s,"SELECT COUNT(*) FROM knowledge_items WHERE "+w+" AND extracted_text IS NOT NULL AND TRIM(extracted_text)<>''"));o.put("supporting_text_empty",count(s,"SELECT COUNT(*) FROM knowledge_items WHERE "+w+" AND status='analyzed' AND (extracted_text IS NULL OR TRIM(extracted_text)='')"));o.put("structured_fields",tableExists(s,"vision_fields")?count(s,"SELECT COUNT(*) FROM vision_fields"):0);o.put("with_actions",count(s,"SELECT COUNT(DISTINCT k.id) FROM knowledge_items k JOIN actions a ON a.item_id=k.id WHERE k.type IN ('SCREENSHOT','IMAGE') AND a.status='open'"));o.put("technical_failures",count(s,"SELECT COUNT(*) FROM knowledge_items WHERE "+w+" AND status IN ('analysis_failed','failed_retryable')"));o.put("queued",count(s,"SELECT COUNT(*) FROM knowledge_items WHERE source='screenshot-folder' AND "+w+" AND status='queued'"));o.put("analyzing",count(s,"SELECT COUNT(*) FROM knowledge_items WHERE source='screenshot-folder' AND "+w+" AND status='analyzing'"));o.put("taught_screenshots",ScreenshotLearning.taughtCount(db));o.put("learned_preference_rules",ScreenshotLearning.learnedPreferenceCount(db));o.put("intent_rows",tableExists(s,"screenshot_intents")?count(s,"SELECT COUNT(*) FROM screenshot_intents WHERE selected=1"):0);o.put("preference_rows",tableExists(s,"screenshot_preferences")?count(s,"SELECT COUNT(*) FROM screenshot_preferences"):0);o.put("legacy_ocr_pass_rows",tableExists(s,"screenshot_ocr_passes")?count(s,"SELECT COUNT(*) FROM screenshot_ocr_passes"):0);return o;}
    private static JSONObject visualStats(Context c,SQLiteDatabase s)throws Exception{JSONObject o=new JSONObject();if(!tableExists(s,"visual_insights")){o.put("active",false);return o;}o.put("active",true);o.put("total",count(s,"SELECT COUNT(*) FROM visual_insights"));o.put("by_status",group(s,"SELECT status,COUNT(*) FROM visual_insights GROUP BY status ORDER BY COUNT(*) DESC"));o.put("by_provider",group(s,"SELECT provider,COUNT(*) FROM visual_insights GROUP BY provider ORDER BY COUNT(*) DESC"));o.put("by_content_type",group(s,"SELECT content_type,COUNT(*) FROM visual_insights GROUP BY content_type ORDER BY COUNT(*) DESC"));o.put("average_usefulness_score",number(s,"SELECT AVG(usefulness_score) FROM visual_insights WHERE status='done'"));o.put("with_search_query",count(s,"SELECT COUNT(*) FROM visual_insights WHERE TRIM(COALESCE(search_query,''))<>''"));o.put("with_recreation_prompt",count(s,"SELECT COUNT(*) FROM visual_insights WHERE TRIM(COALESCE(recreation_prompt,''))<>''"));o.put("with_suggested_actions",count(s,"SELECT COUNT(*) FROM visual_insights WHERE TRIM(COALESCE(intents_json,'')) NOT IN ('','[]')"));o.put("marked_useful",count(s,"SELECT COUNT(*) FROM visual_insights WHERE user_value=1"));o.put("marked_not_useful",count(s,"SELECT COUNT(*) FROM visual_insights WHERE user_value=-1"));o.put("worker_state",VisualInsightStore.workerState(c));o.put("worker_stage",VisualInsightStore.workerStage(c));o.put("worker_detail",VisualInsightStore.workerDetail(c));return o;}
    private static JSONObject graphHealth(SQLiteDatabase s)throws Exception{JSONObject o=new JSONObject();o.put("facets_total",tableExists(s,"memory_facets")?count(s,"SELECT COUNT(*) FROM memory_facets"):0);o.put("relations_total",tableExists(s,"relations")?count(s,"SELECT COUNT(*) FROM relations"):0);o.put("context_packs_total",tableExists(s,"context_packs")?count(s,"SELECT COUNT(*) FROM context_packs"):0);o.put("screenshot_auto_facets",tableExists(s,"memory_facets")?count(s,"SELECT COUNT(*) FROM memory_facets f JOIN knowledge_items k ON k.id=f.item_id WHERE k.source='screenshot-folder' AND k.type IN ('SCREENSHOT','IMAGE') AND f.facet_type<>'USER_PRIORITY'"):0);o.put("screenshot_user_priority_facets",tableExists(s,"memory_facets")?count(s,"SELECT COUNT(*) FROM memory_facets f JOIN knowledge_items k ON k.id=f.item_id WHERE k.source='screenshot-folder' AND f.facet_type='USER_PRIORITY'"):0);o.put("screenshot_auto_relations",tableExists(s,"relations")?count(s,"SELECT COUNT(*) FROM relations r WHERE r.relation IN ('related','same_person','same_project','continuation') AND (r.from_item_id IN (SELECT id FROM knowledge_items WHERE source='screenshot-folder') OR r.to_item_id IN (SELECT id FROM knowledge_items WHERE source='screenshot-folder'))"):0);return o;}
    private static JSONObject smartInboxStats(VaultDb db,SQLiteDatabase s)throws Exception{JSONObject o=new JSONObject();o.put("needs_count",FeatureStore.needs(db,5000).size());o.put("inbox_count",FeatureStore.inbox(db,5000).size());if(tableExists(s,"smart_inbox"))o.put("by_bucket",group(s,"SELECT bucket,COUNT(*) FROM smart_inbox GROUP BY bucket ORDER BY COUNT(*) DESC"));return o;}
    private static JSONObject temporalStats(SQLiteDatabase s)throws Exception{JSONObject o=new JSONObject();if(!tableExists(s,"action_temporal")){o.put("active",false);return o;}o.put("active",true);o.put("resolved_actions",count(s,"SELECT COUNT(*) FROM action_temporal WHERE resolved_at>0"));o.put("open_actions_with_due",count(s,"SELECT COUNT(*) FROM actions WHERE status='open' AND due_text IS NOT NULL AND TRIM(due_text)<>''"));o.put("relative_due_still_stored",count(s,"SELECT COUNT(*) FROM actions WHERE status='open' AND (due_text LIKE '%بكر%' OR lower(due_text) LIKE '%tomorrow%' OR due_text LIKE '%النهاردة%' OR lower(due_text) LIKE '%today%')"));return o;}

    private static JSONArray selfChecks(Context c,VaultDb db,SQLiteDatabase s)throws Exception{JSONArray a=new JSONArray();check(a,"model_download_present",LocalModelManager.filePresent(c),LocalModelManager.filePresent(c)?"GGUF-sized model file exists":"Model file is absent/incomplete","info");check(a,"model_sha_verified",LocalModelManager.verified(c),LocalModelManager.verified(c)?"SHA-256 verification passed":"File is not yet cryptographically verified","warning");LocalLlmRuntime.State rt=LocalLlmRuntime.state(c);check(a,"local_inference_ready",LocalModelManager.installed(c),LocalModelManager.installed(c)?"Real local inference self-test passed":"Runtime state: "+rt.state+(rt.error.isEmpty()?"":" • "+rt.error),LocalModelManager.installed(c)?"ok":"warning");int suspicious=(int)count(s,"SELECT COUNT(DISTINCT k.id) FROM knowledge_items k JOIN actions a ON a.item_id=k.id WHERE k.type IN ('SCREENSHOT','IMAGE') AND a.status='open' AND k.source='screenshot-folder'");check(a,"screenshot_generated_open_actions",suspicious==0,"Folder screenshots with open actions: "+suspicious,suspicious==0?"ok":"warning");int failures=(int)count(s,"SELECT COUNT(*) FROM knowledge_items WHERE type IN ('SCREENSHOT','IMAGE') AND status IN ('analysis_failed','failed_retryable')");check(a,"screenshot_analysis_failures",failures==0,"Screenshot/image analysis failures: "+failures,failures==0?"ok":"warning");int backlog=(int)count(s,"SELECT COUNT(*) FROM knowledge_items WHERE source='screenshot-folder' AND type IN ('SCREENSHOT','IMAGE') AND status='queued'");check(a,"screenshot_backlog",backlog<25,"Queued screenshot analysis: "+backlog,backlog<25?"ok":"info");int graphNoise=tableExists(s,"memory_facets")?(int)count(s,"SELECT COUNT(*) FROM memory_facets f JOIN knowledge_items k ON k.id=f.item_id WHERE k.source='screenshot-folder' AND f.facet_type<>'USER_PRIORITY'"):0;check(a,"screenshot_graph_noise",graphNoise==0,"Non-user screenshot facets: "+graphNoise,graphNoise==0?"ok":"warning");int unresolved=tableExists(s,"actions")?(int)count(s,"SELECT COUNT(*) FROM actions WHERE status='open' AND (due_text LIKE '%بكر%' OR lower(due_text) LIKE '%tomorrow%')"):0;check(a,"relative_due_unresolved",unresolved==0,"Open actions still carrying relative tomorrow text: "+unresolved,unresolved==0?"ok":"warning");int empty=(int)count(s,"SELECT COUNT(*) FROM knowledge_items WHERE type IN ('SCREENSHOT','IMAGE') AND status='analyzed' AND (extracted_text IS NULL OR TRIM(extracted_text)='')");check(a,"screenshots_without_supporting_text",true,"Analyzed images with empty supporting OCR text: "+empty+". This is informational because Visual Intelligence can understand images with zero text.","info");int missing=0;Cursor q=s.rawQuery("SELECT attachment_path FROM knowledge_items WHERE attachment_path IS NOT NULL AND TRIM(attachment_path)<>''",null);while(q.moveToNext()){String p=q.getString(0);if(p!=null&&!new File(p).exists())missing++;}q.close();check(a,"missing_attachment_files",missing==0,"Missing attachment files: "+missing,missing==0?"ok":"warning");int vd=tableExists(s,"visual_insights")?(int)count(s,"SELECT COUNT(*) FROM visual_insights WHERE status='done'"):0,vf=tableExists(s,"visual_insights")?(int)count(s,"SELECT COUNT(*) FROM visual_insights WHERE status='failed'"):0;check(a,"visual_intelligence_results",vd>0,"Visual Intelligence done="+vd+" • failed="+vf,vd>0?(vf==0?"ok":"warning"):"info");CortexAuditStore.Run ar=CortexAuditStore.latest(db);check(a,"full_app_audit_started",ar!=null,ar==null?"No full-app audit has been started yet":"Latest audit #"+ar.id+" • "+ar.status+" • "+ar.progress()+"%",ar==null?"info":"ok");return a;}
    private static void check(JSONArray a,String id,boolean pass,String detail,String severity)throws Exception{JSONObject o=new JSONObject();o.put("id",id);o.put("pass",pass);o.put("severity",severity);o.put("detail",detail);a.put(o);}

    private static JSONObject filesystemInventory(Context c)throws Exception{JSONObject o=new JSONObject();JSONArray roots=new JSONArray();HashSet<String> seen=new HashSet<>();File[] rs={c.getFilesDir(),c.getCacheDir(),c.getNoBackupFilesDir(),c.getDatabasePath("cortex.db").getParentFile(),c.getExternalFilesDir(null)};String[] labels={"files","cache","no_backup","databases","external_files"};for(int i=0;i<rs.length;i++){File r=rs[i];if(r==null)continue;String p=r.getCanonicalPath();if(!seen.add(p))continue;JSONObject x=new JSONObject();x.put("label",labels[i]);x.put("path",p);x.put("free_bytes",r.getFreeSpace());x.put("total_bytes",r.getTotalSpace());JSONArray entries=new JSONArray();walk(r,r,entries,0);x.put("entries",entries);x.put("entry_count",entries.length());roots.put(x);}o.put("roots",roots);o.put("note","File metadata only; binary file contents are not embedded in the debug JSON.");return o;}
    private static void walk(File root,File f,JSONArray out,int depth)throws Exception{if(f==null||!f.exists()||depth>12)return;File[] xs=f.listFiles();if(xs==null)return;Arrays.sort(xs,Comparator.comparing(File::getName));for(File x:xs){JSONObject o=new JSONObject();o.put("relative_path",rel(root,x));o.put("type",x.isDirectory()?"directory":"file");o.put("bytes",x.isFile()?x.length():0);o.put("modified_at",x.lastModified());o.put("readable",x.canRead());o.put("writable",x.canWrite());out.put(o);if(x.isDirectory())walk(root,x,out,depth+1);}}
    private static String rel(File root,File f){try{String a=root.getCanonicalPath(),b=f.getCanonicalPath();return b.startsWith(a)?b.substring(a.length()).replaceFirst("^/",""):b;}catch(Exception e){return f.getPath();}}

    private static JSONArray dumpTable(SQLiteDatabase s,String table)throws Exception{return dumpQuery(s,"SELECT * FROM "+qi(table)+" ORDER BY 1");}
    private static JSONArray dumpQuery(SQLiteDatabase s,String sql)throws Exception{JSONArray out=new JSONArray();Cursor c=s.rawQuery(sql,null);String[] cols=c.getColumnNames();while(c.moveToNext()){JSONObject row=new JSONObject();for(int i=0;i<cols.length;i++){if(c.isNull(i)){row.put(cols[i],JSONObject.NULL);continue;}int type=c.getType(i);if(type==Cursor.FIELD_TYPE_INTEGER)row.put(cols[i],c.getLong(i));else if(type==Cursor.FIELD_TYPE_FLOAT)row.put(cols[i],c.getDouble(i));else if(type==Cursor.FIELD_TYPE_BLOB)row.put(cols[i],"<BLOB "+c.getBlob(i).length+" bytes>");else row.put(cols[i],c.getString(i));}out.put(row);}c.close();return out;}
    private static JSONArray group(SQLiteDatabase s,String sql)throws Exception{JSONArray out=new JSONArray();Cursor c=s.rawQuery(sql,null);while(c.moveToNext()){JSONObject o=new JSONObject();o.put("value",c.isNull(0)?"<null>":c.getString(0));o.put("count",c.getLong(1));out.put(o);}c.close();return out;}
    private static long count(SQLiteDatabase s,String sql){Cursor c=s.rawQuery(sql,null);long n=c.moveToFirst()?c.getLong(0):0;c.close();return n;}
    private static String scalar(SQLiteDatabase s,String sql){Cursor c=s.rawQuery(sql,null);String x=c.moveToFirst()&&!c.isNull(0)?c.getString(0):"";c.close();return x;}
    private static int rowCount(SQLiteDatabase s,String sql){Cursor c=s.rawQuery(sql,null);int n=c.getCount();c.close();return n;}
    private static double number(SQLiteDatabase s,String sql){Cursor c=s.rawQuery(sql,null);double n=c.moveToFirst()&&!c.isNull(0)?c.getDouble(0):0;c.close();return n;}
    private static boolean tableExists(SQLiteDatabase s,String t){Cursor c=s.rawQuery("SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1",new String[]{t});boolean b=c.moveToFirst();c.close();return b;}
    private static String qi(String x){return"\""+x.replace("\"","\"\"")+"\"";}
    private static String iso(long ms){return new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ssXXX",Locale.US).format(new Date(ms));}
    private static void share(Activity a,File f){try{Uri u=FileProvider.getUriForFile(a,a.getPackageName()+".feedback.files",f);Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/json");i.putExtra(Intent.EXTRA_STREAM,u);i.putExtra(Intent.EXTRA_SUBJECT,"Cortex Exhaustive Debug Snapshot");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);a.startActivity(Intent.createChooser(i,"Share Cortex full debug snapshot"));}catch(Exception e){android.widget.Toast.makeText(a,"Share failed: "+e.getMessage(),android.widget.Toast.LENGTH_LONG).show();}}
}
